static long countPairs(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();
    long pairs = 0;
    for (int x : nums) {
        int need = target - x;
        pairs += seen.getOrDefault(need, 0);
        seen.merge(x, 1, Integer::sum);
    }
    return pairs;
}

