long long countPairs(const vector<int>& nums, int target) {
    unordered_map<int, int> seen;
    seen.reserve(nums.size() * 2);
    long long pairs = 0;
    for (int x : nums) {
        int need = target - x;
        auto it = seen.find(need);
        if (it != seen.end()) pairs += it->second;
        seen[x]++;
    }
    return pairs;
}

