typedef struct {
    int *keys, *counts;
    bool *used;
    size_t mask;
} CountMap;

static size_t cm_slot(const CountMap* m, int key) {
    size_t i = ((uint32_t)key * 2654435761u) & m->mask;
    while (m->used[i] && m->keys[i] != key) i = (i + 1) & m->mask;
    return i;
}

long long countPairs(const int* nums, int n, int target) {
    size_t cap = 16;
    while (cap < 2 * (size_t)n) cap <<= 1;
    CountMap seen = {malloc(cap * sizeof(int)), calloc(cap, sizeof(int)), calloc(cap, sizeof(bool)), cap - 1};
    long long pairs = 0;
    for (int j = 0; j < n; j++) {
        int need = target - nums[j];
        size_t i = cm_slot(&seen, need);
        if (seen.used[i]) pairs += seen.counts[i];
        i = cm_slot(&seen, nums[j]);
        seen.used[i] = true;
        seen.keys[i] = nums[j];
        seen.counts[i]++;
    }
    free(seen.keys); free(seen.counts); free(seen.used);
    return pairs;
}

