static int[] firstPair(int[] nums, int target) {
    Map<Integer, Integer> where = new HashMap<>();
    for (int j = 0; j < nums.length; j++) {
        int need = target - nums[j];
        Integer i = where.get(need);
        if (i != null) return new int[] {i, j};
        where.putIfAbsent(nums[j], j);
    }
    return new int[] {-1, -1};
