typedef struct {
    int *keys, *idx;
    bool *used;
    size_t mask;
} IndexMap;

static size_t im_slot(const IndexMap* m, int key) {
    size_t i = ((uint32_t)key * 2654435761u) & m->mask;
    while (m->used[i] && m->keys[i] != key) i = (i + 1) & m->mask;
    return i;
}

void firstPair(const int* nums, int n, int target, int out[2]) {
    size_t cap = 16;
    while (cap < 2 * (size_t)n) cap <<= 1;
    IndexMap where = {malloc(cap * sizeof(int)), malloc(cap * sizeof(int)), calloc(cap, sizeof(bool)), cap - 1};
    out[0] = out[1] = -1;
    for (int j = 0; j < n; j++) {
        int need = target - nums[j];
        size_t i = im_slot(&where, need);
        if (where.used[i]) {
            out[0] = where.idx[i];
            out[1] = j;
            break;
        }
        i = im_slot(&where, nums[j]);
        if (!where.used[i]) {
            where.used[i] = true;
            where.keys[i] = nums[j];
            where.idx[i] = j;
        }
    }
    free(where.keys); free(where.idx); free(where.used);
}

